/**
 * Generates the QA build-time capability flags file.
 *
 * The `npm run package:qa` pipeline invokes this before TypeScript compilation.
 * It writes electron/config/build-flags.qa.ts with
 * ALLOW_FIREBASE_EMULATORS = true. The package script copies that compiled
 * module over the production-default flag in the QA output and removes the
 * temporary source and module.
 *
 * The generated file is NOT committed to git (see .gitignore).
 *
 * Usage:
 *   DRUG_MANAGER_QA_BUILD=1 node scripts/generate-qa-build-flags.mjs
 *
 * The DRUG_MANAGER_QA_BUILD environment variable is read ONLY during the build
 * pipeline to decide whether to generate QA flags. It is NOT read by the
 * packaged application at runtime, so setting it when running the installed
 * production .exe has no effect.
 */
import { writeFileSync } from 'node:fs';

const isQABuild = process.env.DRUG_MANAGER_QA_BUILD === '1';

if (!isQABuild) {
  console.error('[generate-qa-build-flags] DRUG_MANAGER_QA_BUILD is not set to 1; refusing to generate QA flags.');
  process.exit(1);
}

const targetPath = 'electron/config/build-flags.qa.ts';
const content = `// Auto-generated QA build flags. Do NOT edit or commit manually.
// Generated by scripts/generate-qa-build-flags.mjs during QA packaging.
// ALLOW_FIREBASE_EMULATORS is true only in this generated QA build.
export const ALLOW_FIREBASE_EMULATORS = true;
`;

writeFileSync(targetPath, content, { encoding: 'utf8' });
console.log(`[generate-qa-build-flags] Wrote ${targetPath} (ALLOW_FIREBASE_EMULATORS = true)`);
